    medicationReportDays:medicationDays.length,medicationReportCoveragePercent:days.length?100*medicationDays.length/days.length:null,
    controllerMarkedDoses,controllerSlots,controllerRatePercent:controllerSlots?100*controllerMarkedDoses/controllerSlots:null,
    relieverDays:medicationDays.filter(d=>d.rescue>0).length,relieverReportDays:medicationDays.length,
