  if(!Number.isFinite(change))return {tone:'neutral',arrow:'',label:'No comparison',accessibleLabel:`Insufficient or missing comparison evidence for ${metricName}.`};
  if(change===0)return {tone:'neutral',arrow:'→',label:'No change',accessibleLabel:`No change in ${metricName}.`};
