  if(!direction)return {tone:'neutral',arrow,label:'Direction not interpreted',accessibleLabel:`${change>0?'Increase':'Decrease'} in ${metricName}; this change is not interpreted as a clinical improvement or worsening.`};
  const favorable=change*direction>0;
  return {tone:favorable?'good':'bad',arrow,label:favorable?'Favorable':'Unfavorable',accessibleLabel:`${favorable?'Favorable':'Unfavorable'} ${change>0?'increase':'decrease'} in ${metricName}.`};
