  const trend=`<div class="minute-trend ${status.tone}" role="img" aria-label="${status.accessibleLabel}${comparisonInfo?.available?` ${comparisonInfo.text}.`:''}"><span class="trend-status">${status.label}</span>${measure}</div>`;
  return `<article class="minute-card"><div class="minute-label"><span>${label}</span><button class="minute-help" type="button" aria-label="About ${label}: ${help}" title="${help}">?</button></div><div class="minute-value">${display.main}</div>${display.detail?`<div class="minute-unit">${display.detail}</div>`:''}${trend}</article>`;
