  if(kind==='symptoms')return tracker?`Tracker submitted: ${day.symptoms.length?day.symptoms.join(', '):'no symptoms reported'}; school impact: ${day.school===null?'unknown':day.school?'absence reported':'no absence reported'}.`:'No tracker submission; symptoms and school impact are unknown.';
