    const index=offset+1,last=[...days].reverse().find(d=>d.trackerSubmitted??!d.missing),initials=p.name.split(' ').map(x=>x[0]).join(''),label=signals.length?`${signals.length} follow-up cue${signals.length===1?'':'s'}`:'No comparison cue';
