    const fevEvidence=`Accepted FEV1 median daily best: ${currentStats.medianDailyBestLiters===null?'not available':`${currentStats.medianDailyBestLiters.toFixed(2)} L across ${currentStats.acceptedDailyBestDays} days`} vs prior week ${previousStats.medianDailyBestLiters===null?'not available':`${previousStats.medianDailyBestLiters.toFixed(2)} L across ${previousStats.acceptedDailyBestDays} days`}; ${currentStats.excludedAttempts} rejected or conflicting attempts excluded from the trend.`;
